<?php
declare(strict_types=1); require_once __DIR__.'/bootstrap.php'; admin_require_login();
$products=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();
$activeProducts=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn();
$orders=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();
$pending=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn();
$customers=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();
$lowStock=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock_quantity <= low_stock_threshold AND is_active=1')->fetchColumn();
$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE payment_status='paid' AND status <> 'cancelled'")->fetchColumn();
$recent=$pdo->query('SELECT id,order_number,customer_name,total_amount,status,payment_status,placed_at FROM orders ORDER BY placed_at DESC LIMIT 8')->fetchAll();

$months=[];$traffic=[];$ordersSeries=[];$revenueSeries=[];$profitSeries=[];
for($i=5;$i>=0;$i--){$key=date('Y-m',strtotime("first day of -$i month"));$months[] = date('M Y',strtotime($key.'-01'));$traffic[$key]=0;$ordersSeries[$key]=0;$revenueSeries[$key]=0;$profitSeries[$key]=0;}
try{$st=$pdo->query("SELECT DATE_FORMAT(viewed_at,'%Y-%m') ym,COUNT(*) total FROM page_views WHERE viewed_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY ym");foreach($st as $x)if(isset($traffic[$x['ym']]))$traffic[$x['ym']]=(int)$x['total'];}catch(Throwable $e){}
try{$st=$pdo->query("SELECT DATE_FORMAT(placed_at,'%Y-%m') ym,COUNT(*) orders_count,SUM(CASE WHEN payment_status='paid' AND status<>'cancelled' THEN total_amount ELSE 0 END) revenue FROM orders WHERE placed_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY ym");foreach($st as $x)if(isset($ordersSeries[$x['ym']])){$ordersSeries[$x['ym']]=(int)$x['orders_count'];$revenueSeries[$x['ym']]=(float)$x['revenue'];}}catch(Throwable $e){}
try{$st=$pdo->query("SELECT DATE_FORMAT(o.placed_at,'%Y-%m') ym,SUM(CASE WHEN o.payment_status='paid' AND o.status<>'cancelled' THEN oi.quantity*(oi.unit_price-COALESCE(p.cost_price,0)) ELSE 0 END) profit FROM orders o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN products p ON p.id=oi.product_id WHERE o.placed_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY ym");foreach($st as $x)if(isset($profitSeries[$x['ym']]))$profitSeries[$x['ym']]=(float)$x['profit'];}catch(Throwable $e){}
$statuses=$pdo->query("SELECT status,COUNT(*) total FROM orders GROUP BY status")->fetchAll();$monthKeys=array_keys($traffic);

admin_page_start('Dashboard'); ?>
<div class="row g-3 mb-4">
<?php foreach ([['Products',$products,'bi-box-seam'],['Active products',$activeProducts,'bi-check-circle'],['Orders',$orders,'bi-bag-check'],['Pending orders',$pending,'bi-clock-history'],['Customers',$customers,'bi-people'],['Low-stock products',$lowStock,'bi-exclamation-triangle']] as $m): ?><div class="col-6 col-xl-4"><div class="metric-card"><div class="d-flex justify-content-between align-items-start"><div><div class="text-secondary small mb-2"><?= e($m[0]) ?></div><div class="metric-value"><?= number_format((int)$m[1]) ?></div></div><div class="metric-icon"><i class="bi <?= e($m[2]) ?>"></i></div></div></div></div><?php endforeach; ?>
<div class="col-12"><div class="metric-card d-flex align-items-center justify-content-between flex-wrap gap-3"><div><div class="text-secondary small">Recorded paid revenue</div><div class="metric-value"><?= e(money($revenue)) ?></div><div class="text-secondary small">Calculated only from orders marked paid; demo data may be empty.</div></div><a class="btn btn-primary" href="products.php?action=new"><i class="bi bi-plus-lg me-1"></i> Add product</a></div></div></div>
<div class="row g-3 mb-4"><div class="col-xl-6"><div class="panel"><h2 class="h5">Website traffic</h2><canvas id="trafficChart" height="150"></canvas></div></div><div class="col-xl-6"><div class="panel"><h2 class="h5">Orders over time</h2><canvas id="ordersChart" height="150"></canvas></div></div><div class="col-xl-6"><div class="panel"><h2 class="h5">Revenue and estimated gross profit</h2><canvas id="profitChart" height="150"></canvas><small class="text-secondary">Gross profit estimate uses paid order items and current product cost prices; historical cost changes are not tracked.</small></div></div><div class="col-xl-6"><div class="panel"><h2 class="h5">Orders by status</h2><canvas id="statusChart" height="150"></canvas></div></div></div>
<div class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Recent orders</h2><a href="orders.php" class="btn btn-sm btn-outline-primary">View all orders</a></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Order status</th><th>Payment</th><th>Date</th></tr></thead><tbody><?php if (!$recent): ?><tr><td colspan="6" class="text-center text-secondary py-4">No orders yet. New orders will appear here.</td></tr><?php else: foreach($recent as $r): ?><tr><td><a href="orders.php?view=<?= (int)$r['id'] ?>" class="fw-semibold"><?= e($r['order_number']) ?></a></td><td><?= e($r['customer_name']) ?></td><td><?= e(money($r['total_amount'])) ?></td><td><span class="badge text-bg-light border status-pill"><?= e(ucfirst($r['status'])) ?></span></td><td><?= e(ucfirst($r['payment_status'])) ?></td><td><?= e($r['placed_at']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const labels=<?=json_encode($months)?>;const traffic=<?=json_encode(array_values($traffic))?>;const orderCounts=<?=json_encode(array_values($ordersSeries))?>;const revenue=<?=json_encode(array_values($revenueSeries))?>;const profit=<?=json_encode(array_values($profitSeries))?>;const statuses=<?=json_encode(array_column($statuses,'status'))?>;const statusCounts=<?=json_encode(array_map('intval',array_column($statuses,'total')))?>;if(window.Chart){new Chart(document.getElementById('trafficChart'),{type:'line',data:{labels,datasets:[{label:'Page views',data:traffic,tension:.3}]},options:{responsive:true}});new Chart(document.getElementById('ordersChart'),{type:'bar',data:{labels,datasets:[{label:'Orders',data:orderCounts}]},options:{responsive:true}});new Chart(document.getElementById('profitChart'),{type:'line',data:{labels,datasets:[{label:'Paid revenue (KES)',data:revenue,tension:.3},{label:'Estimated gross profit (KES)',data:profit,tension:.3}]},options:{responsive:true}});new Chart(document.getElementById('statusChart'),{type:'pie',data:{labels:statuses,datasets:[{data:statusCounts}]},options:{responsive:true}});}</script><?php admin_page_end(); ?>
